B.aXc=new A.ai("Brightness Slider",A.cAD(),"import 'package:docs/shadcn_ui.dart';\n\nclass SliderExample1 extends StatefulWidget {\n  const SliderExample1({super.key});\n\n  @override\n  State<SliderExample1> createState() => _SliderExample1State();\n}\n\nclass _SliderExample1State extends State<SliderExample1> {\n  double value = 0.64;\n\n  @override\n  Widget build(BuildContext context) {\n    return BrightnessSlider(\n      value: value,\n      onChanged: (next) {\n        setState(() => value = next);\n      },\n    );\n  }\n}\n")
B.aWX=new A.ai("Range Slider",A.cAE(),"import 'package:docs/shadcn_ui.dart';\nimport 'package:docs/ui/shadcn/components/form/slider/_impl/core/shad_slider_models.dart'\n    show ShadRangeValue;\n\nclass SliderExample2 extends StatefulWidget {\n  const SliderExample2({super.key});\n\n  @override\n  State<SliderExample2> createState() => _SliderExample2State();\n}\n\nclass _SliderExample2State extends State<SliderExample2> {\n  ShadRangeValue value = const ShadRangeValue(240, 980, minRange: 120);\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        RangeSoftSlider(\n          min: 0,\n          max: 1600,\n          rangeValue: value,\n          onChanged: (next) {\n            setState(() => value = next);\n          },\n        ),\n        const Gap(16),\n        Text(\n          'Price: $' + value.start.round().toString() + ' - $' + value.end.round().toString(),\n        ),\n      ],\n    );\n  }\n}\n")
B.aW3=new A.ai("Steps + Dots Slider",A.cAF(),"import 'package:docs/shadcn_ui.dart';\n\nclass SliderExample3 extends StatefulWidget {\n  const SliderExample3({super.key});\n\n  @override\n  State<SliderExample3> createState() => _SliderExample3State();\n}\n\nclass _SliderExample3State extends State<SliderExample3> {\n  double value = 6;\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        StepsDotsSlider(\n          min: 0,\n          max: 12,\n          steps: 12,\n          value: value,\n          onChanged: (next) {\n            setState(() => value = next);\n          },\n        ),\n        const Gap(16),\n        Text('Step: ${value.round()}'),\n      ],\n    );\n  }\n}\n")
B.aYp=new A.ai("Wave Slider (Pricing)",A.cAG(),"import 'package:docs/shadcn_ui.dart';\nimport 'package:docs/ui/shadcn/components/form/slider/_impl/core/shad_slider_models.dart'\n    show ShadPopoverVisibility;\nimport 'package:docs/ui/shadcn/components/form/slider/_impl/styles/shad_slider_defaults.dart'\n    show ShadSliderDefaults;\n\nclass SliderExample4 extends StatefulWidget {\n  const SliderExample4({super.key});\n\n  @override\n  State<SliderExample4> createState() => _SliderExample4State();\n}\n\nclass _SliderExample4State extends State<SliderExample4> {\n  double price = 420;\n\n  static const List<double> samples = [\n    0.12, 0.2, 0.32, 0.44, 0.51, 0.58, 0.64, 0.55, 0.7, 0.82, 0.68,\n    0.5, 0.62, 0.74, 0.66, 0.53, 0.42, 0.37, 0.29, 0.24, 0.2, 0.16,\n  ];\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        WaveSlider.domain(\n          min: 120,\n          max: 1600,\n          value: price,\n          samples: samples,\n          onChanged: (next) => setState(() => price = next),\n          valueFormatter: (value) => '$' + value.round().toString(),\n          popoverVisibility: ShadPopoverVisibility.always,\n          popoverBuilder: ShadSliderDefaults.valuePopoverPill(\n            formatter: (value) => '$' + value.round().toString(),\n          ),\n        ),\n        const Gap(12),\n        Text('Selected: $' + price.round().toString()),\n      ],\n    );\n  }\n}\n")
B.aY4=new A.ai("Slider Playground (Sidebar Controls)",A.cAH(),"import 'package:docs/shadcn_ui.dart';\nimport 'package:flutter/material.dart' as m hide Slider;\n\n/// Interactive playground with a sidebar panel that exposes\n/// most slider customization options live.\nclass SliderExample5 extends StatefulWidget {\n  const SliderExample5({super.key});\n\n  @override\n  State<SliderExample5> createState() => _SliderExample5State();\n}\n\nclass _SliderExample5State extends State<SliderExample5> {\n  double value = 0.72;\n  double min = 0;\n  double max = 1;\n  bool enabled = true;\n  bool fillStopsAtThumbCenter = false;\n  bool popoverAlways = false;\n\n  double trackHeight = 30;\n  double trackRadius = 16;\n  double joinGapPx = 2;\n  double fillEdgeBiasPx = 0;\n  double thumbEdgeOffsetPx = 0;\n  double thumbVerticalOffsetPx = 0;\n  double thumbWidth = 10;\n  double thumbHeight = 25;\n  double thumbRadius = 4;\n  double thumbInsideOffsetPx = 4;\n\n  String preset = 'brightness';\n\n  @override\n  Widget build(BuildContext context) {\n    final maxSafe = max <= min ? min + 0.1 : max;\n    value = value.clamp(min, maxSafe);\n\n    return Slider.single(\n      min: min,\n      max: maxSafe,\n      value: value,\n      enabled: enabled,\n      preset: preset,\n      trackHeight: trackHeight,\n      trackRadius: trackRadius,\n      joinGapPx: joinGapPx,\n      fillEdgeBiasPx: fillEdgeBiasPx,\n      fillStopsAtThumbCenter: fillStopsAtThumbCenter,\n      thumbEdgeOffsetPx: thumbEdgeOffsetPx,\n      thumbVerticalOffsetPx: thumbVerticalOffsetPx,\n      thumbSize: Size(thumbWidth, thumbHeight),\n      thumbBuilder: ShadSliderDefaults.barThumb(\n        radius: thumbRadius,\n        insideOffsetPx: thumbInsideOffsetPx,\n      ),\n      dragPopoverVisibility: popoverAlways\n          ? ShadPopoverVisibility.always\n          : ShadPopoverVisibility.whileDragging,\n      dragPopoverBuilder: ShadSliderDefaults.valuePopoverRounded(\n        formatter: (v) => '${(v * 100).round()}%',\n      ),\n      onChanged: (next) => setState(() => value = next),\n    );\n  }\n}\n")
