B.aXW=new A.ai("Example",A.cz5(),"import 'package:flutter/services.dart';\nimport 'package:docs/shadcn_ui.dart';\nimport 'package:docs/ui/shadcn/components/overlay/menu/menu.dart';\nimport 'package:docs/ui/shadcn/components/overlay/menubar/menubar.dart';\n\nclass MenubarExample1 extends StatefulWidget {\n  const MenubarExample1({super.key});\n\n  @override\n  State<MenubarExample1> createState() => _MenubarExample1State();\n}\n\nclass _MenubarExample1State extends State<MenubarExample1> {\n  bool _showBookmarksBar = false;\n  bool _showFullURLs = true;\n  int _selectedProfile = 1;\n  @override\n  Widget build(BuildContext context) {\n    // Typical desktop-style menubar with nested submenus, shortcuts,\n    // checkboxes (non-closing), and a radio group.\n    return Menubar(\n      children: [\n        const MenuButton(\n          subMenu: [\n            MenuButton(\n              leading: Icon(RadixIcons.filePlus),\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyT,\n                  control: true,\n                ),\n              ),\n              child: Text('New Tab'),\n            ),\n            MenuButton(\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyN,\n                  control: true,\n                ),\n              ),\n              child: Text('New Window'),\n            ),\n            MenuButton(\n              enabled: false,\n              child: Text('New Incognito Window'),\n            ),\n            MenuDivider(),\n            MenuButton(\n              subMenu: [\n                MenuButton(\n                  child: Text('Email Link'),\n                ),\n                MenuButton(\n                  child: Text('Messages'),\n                ),\n                MenuButton(\n                  child: Text('Notes'),\n                ),\n              ],\n              child: Text('Share'),\n            ),\n            MenuButton(\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyP,\n                  control: true,\n                ),\n              ),\n              child: Text('Print'),\n            ),\n            MenuButton(\n              subMenu: [\n                MenuButton(\n                  child: Text('Save and Exit'),\n                ),\n                MenuButton(\n                  child: Text('Discard and Exit'),\n                ),\n              ],\n              child: Text('Exit'),\n            ),\n          ],\n          child: Text('File'),\n        ),\n        const MenuButton(\n          subMenu: [\n            MenuButton(\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyZ,\n                  control: true,\n                ),\n              ),\n              child: Text('Undo'),\n            ),\n            MenuButton(\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyZ,\n                  control: true,\n                  shift: true,\n                ),\n              ),\n              child: Text('Redo'),\n            ),\n            MenuDivider(),\n            MenuButton(\n              subMenu: [\n                MenuButton(\n                  child: Text('Search the Web'),\n                ),\n                MenuDivider(),\n                MenuButton(\n                  child: Text('Find...'),\n                ),\n                MenuButton(\n                  child: Text('Find Next'),\n                ),\n                MenuButton(\n                  child: Text('Find Previous'),\n                ),\n              ],\n              child: Text('Find'),\n            ),\n            MenuDivider(),\n            MenuButton(\n              child: Text('Cut'),\n            ),\n            MenuButton(\n              child: Text('Copy'),\n            ),\n            MenuButton(\n              child: Text('Paste'),\n            ),\n          ],\n          child: Text('Edit'),\n        ),\n        MenuButton(\n          subMenu: [\n            MenuCheckbox(\n              value: _showBookmarksBar,\n              onChanged: (context, value) {\n                setState(() {\n                  _showBookmarksBar = value;\n                });\n              },\n              // Keep the submenu open while toggling for quicker multi-actions.\n              autoClose: false,\n              child: const Text('Always Show Bookmarks Bar'),\n            ),\n            MenuCheckbox(\n              value: _showFullURLs,\n              onChanged: (context, value) {\n                setState(() {\n                  _showFullURLs = value;\n                });\n              },\n              // Also keep open here to demonstrate autoClose control.\n              autoClose: false,\n              child: const Text('Always Show Full URLs'),\n            ),\n            const MenuDivider(),\n            const MenuButton(\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyR,\n                  control: true,\n                ),\n              ),\n              child: Text('Reload'),\n            ),\n            const MenuButton(\n              enabled: false,\n              trailing: MenuShortcut(\n                activator: SingleActivator(\n                  LogicalKeyboardKey.keyR,\n                  control: true,\n                  shift: true,\n                ),\n              ),\n              child: Text('Force Reload'),\n            ),\n            const MenuDivider(),\n            const MenuButton(\n              child: Text('Toggle Full Screen'),\n            ),\n            const MenuDivider(),\n            const MenuButton(\n              child: Text('Hide Sidebar'),\n            ),\n          ],\n          child: const Text('View'),\n        ),\n        MenuButton(\n          subMenu: [\n            MenuRadioGroup<int>(\n              value: _selectedProfile,\n              onChanged: (context, value) {\n                setState(() {\n                  _selectedProfile = value;\n                });\n              },\n              children: const [\n                MenuRadio<int>(\n                  value: 0,\n                  // Disable auto-close to let users quickly toggle multiple options.\n                  autoClose: false,\n                  child: Text('Andy'),\n                ),\n                MenuRadio<int>(\n                  value: 1,\n                  autoClose: false,\n                  child: Text('Benoit'),\n                ),\n                MenuRadio<int>(\n                  value: 2,\n                  autoClose: false,\n                  child: Text('Luis'),\n                ),\n              ],\n            ),\n            const MenuDivider(),\n            const MenuButton(\n              child: Text('Edit...'),\n            ),\n            const MenuDivider(),\n            const MenuButton(\n              child: Text('Add Profile...'),\n            ),\n          ],\n          child: const Text('Profiles'),\n        ),\n      ],\n    );\n  }\n}\n")
