B.aVU=new A.ai("Horizontal Divider Example",A.cx3(),"import 'package:docs/shadcn_ui.dart';\n\n/// Horizontal dividers between list items.\n///\n/// Use [Divider] to visually separate vertically-stacked content.\nclass DividerExample1 extends StatelessWidget {\n  const DividerExample1({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const SizedBox(\n      width: 300,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          Text('Item 1'),\n          Divider(),\n          Text('Item 2'),\n          Divider(),\n          Text('Item 3'),\n        ],\n      ),\n    );\n  }\n}\n")
B.aVx=new A.ai("Vertical Divider Example",A.cx4(),"import 'package:docs/shadcn_ui.dart';\n\n/// Vertical dividers between columns.\n///\n/// Use [VerticalDivider] to separate horizontally-arranged content.\nclass DividerExample2 extends StatelessWidget {\n  const DividerExample2({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const SizedBox(\n      width: 300,\n      height: 100,\n      child: Row(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          Expanded(child: Text('Item 1')),\n          VerticalDivider(),\n          Expanded(child: Text('Item 2')),\n          VerticalDivider(),\n          Expanded(child: Text('Item 3')),\n        ],\n      ),\n    );\n  }\n}\n")
B.aWz=new A.ai("Divider with Text Example",A.cx5(),"import 'package:docs/shadcn_ui.dart';\n\n/// Dividers with centered labels.\n///\n/// [Divider.child] can render text or other widgets inline with the rule.\nclass DividerExample3 extends StatelessWidget {\n  const DividerExample3({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const SizedBox(\n      width: 300,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          Text('Item 1'),\n          Divider(\n            child: Text('Divider'),\n          ),\n          Text('Item 2'),\n          Divider(\n            child: Text('Divider'),\n          ),\n          Text('Item 3'),\n        ],\n      ),\n    );\n  }\n}\n")
B.aXf=new A.ai("Divider Splitter Example",A.cx6(),"import 'package:docs/shadcn_ui.dart';\nimport 'package:docs/ui/shadcn/components/layout/flex/flex.dart' show PaintOrder;\n\n/// Divider splitter-style example with interactive center control.\nclass DividerExample4 extends StatelessWidget {\n  const DividerExample4({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return OutlinedContainer(\n      width: 600,\n      height: 400,\n      child: Row(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          Container(\n            color: Theme.of(context).colorScheme.border.withAlpha(64),\n            width: 100,\n            child: ListView.builder(\n              itemCount: 50,\n              itemBuilder: (context, index) {\n                return Button.ghost(\n                  onPressed: () {},\n                  child: Text('Button $index'),\n                );\n              },\n            ),\n          ),\n          PaintOrder(\n            paintOrder: 3,\n            child: VerticalDivider(\n              childAlignment: const AxisAlignment(-0.6),\n              padding: EdgeInsets.zero,\n              child: IconButton.outline(\n                icon: const Icon(Icons.arrow_back_ios_new),\n                shape: ButtonShape.circle,\n                size: ButtonSize.small,\n                onPressed: () {},\n              ),\n            ),\n          ),\n          const Expanded(\n            child: ColoredBox(\n              color: Colors.black,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n")
