B.aXp=new A.ai("Profile sheet",A.cAv(),"import 'package:docs/shadcn_ui.dart';\n\nclass SheetExample1 extends StatefulWidget {\n  const SheetExample1({super.key});\n\n  @override\n  State<SheetExample1> createState() => _SheetExample1State();\n}\n\nclass _SheetExample1State extends State<SheetExample1> {\n  final FormController controller = FormController();\n\n  @override\n  Widget build(BuildContext context) {\n    return PrimaryButton(\n      onPressed: () {\n        openSheet(\n          context: context,\n          builder: (context) {\n            return Container(\n              padding: const EdgeInsets.all(24),\n              constraints: const BoxConstraints(maxWidth: 420),\n              child: Form(\n                controller: controller,\n                child: Column(\n                  mainAxisSize: MainAxisSize.min,\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Row(\n                      children: [\n                        Expanded(\n                          child: const Text('Edit profile').large().medium(),\n                        ),\n                        TextButton(\n                          density: ButtonDensity.icon,\n                          child: const Icon(Icons.close),\n                          onPressed: () => closeSheet(context),\n                        ),\n                      ],\n                    ),\n                    const Gap(8),\n                    const Text(\n                      'Make changes to your profile here. Click save when you\\'re done.',\n                    ).muted(),\n                    const Gap(16),\n                    FormTableLayout(\n                      rows: [\n                        FormField<String>(\n                          key: const FormKey(#name),\n                          label: const Text('Name'),\n                          validator: const NotEmptyValidator() &\n                              const LengthValidator(min: 4),\n                          child: const TextField(\n                            initialValue: 'M Ibrar',\n                            placeholder: Text('Your full name'),\n                          ),\n                        ),\n                        FormField<String>(\n                          key: const FormKey(#username),\n                          label: const Text('Username'),\n                          validator: const NotEmptyValidator() &\n                              const LengthValidator(min: 4),\n                          child: const TextField(\n                            initialValue: '@mibrar-dev',\n                            placeholder: Text('Your username'),\n                          ),\n                        ),\n                      ],\n                    ),\n                    const Gap(16),\n                    Align(\n                      alignment: AlignmentDirectional.centerEnd,\n                      child: FormErrorBuilder(\n                        builder: (context, errors, child) {\n                          return PrimaryButton(\n                            onPressed: errors.isNotEmpty\n                                ? null\n                                : () {\n                                    context.submitForm();\n                                  },\n                            child: const Text('Save changes'),\n                          );\n                        },\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            );\n          },\n          position: OverlayPosition.end,\n        );\n      },\n      child: const Text('Open Sheet'),\n    );\n  }\n}")
