B.aXO=new A.ai("Example",A.czl(),"import 'package:shadcn_flutter/shadcn_flutter.dart';\n\nclass NumberInputExample1 extends StatefulWidget {\n  const NumberInputExample1({super.key});\n\n  @override\n  State<NumberInputExample1> createState() => _NumberInputExample1State();\n}\n\nclass _NumberInputExample1State extends State<NumberInputExample1> {\n  double value = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        SizedBox(\n          width: 100,\n          child: TextField(\n            initialValue: value.toString(),\n            onChanged: (value) {\n              setState(() {\n                this.value = double.tryParse(value) ?? 0;\n              });\n            },\n            features: const [\n              // Adds stepper/spinner controls to nudge the value up/down.\n              InputFeature.spinner(),\n            ],\n            submitFormatters: [\n              // Allow math expressions (e.g., 1+2*3) that resolve on submit.\n              TextInputFormatters.mathExpression(),\n            ],\n          ),\n        ),\n        const Gap(8),\n        Text('Value: $value'),\n      ],\n    );\n  }\n}\n")
B.aXn=new A.ai("Spinner + Plus/Minus",A.czm(),"import 'package:shadcn_flutter/shadcn_flutter.dart';\n\nclass NumberInputExample2 extends StatefulWidget {\n  const NumberInputExample2({super.key});\n\n  @override\n  State<NumberInputExample2> createState() => _NumberInputExample2State();\n}\n\nclass _NumberInputExample2State extends State<NumberInputExample2> {\n  static const double _min = 0;\n  static const double _max = 64;\n\n  late final TextEditingController _spinnerController;\n  late final TextEditingController _stepperController;\n\n  double value = 8;\n\n  @override\n  void initState() {\n    super.initState();\n    _spinnerController = TextEditingController(text: value.toStringAsFixed(0));\n    _stepperController = TextEditingController(text: value.toStringAsFixed(0));\n  }\n\n  @override\n  void dispose() {\n    _spinnerController.dispose();\n    _stepperController.dispose();\n    super.dispose();\n  }\n\n  void _syncValue(double nextValue) {\n    final clamped = nextValue.clamp(_min, _max).toDouble();\n    final text = clamped.toStringAsFixed(0);\n    setState(() {\n      value = clamped;\n      _spinnerController.text = text;\n      _stepperController.text = text;\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        const Text('Spinner').medium(),\n        const Gap(8),\n        SizedBox(\n          width: 140,\n          child: TextField(\n            controller: _spinnerController,\n            submitFormatters: [\n              TextInputFormatters.digitsOnly(min: _min, max: _max),\n            ],\n            features: const [\n              InputFeature.spinner(step: 1, enableGesture: false),\n            ],\n            onChanged: (text) {\n              final parsed = double.tryParse(text);\n              if (parsed != null) {\n                _syncValue(parsed);\n              }\n            },\n          ),\n        ),\n        const Gap(16),\n        const Text('Plus / Minus stepper').medium(),\n        const Gap(8),\n        SizedBox(\n          width: 240,\n          child: Row(\n            children: [\n              IconButton.outline(\n                density: ButtonDensity.iconDense,\n                size: ButtonSize.small,\n                icon: const Icon(Icons.remove),\n                onPressed: () => _syncValue(value - 1),\n              ),\n              const Gap(8),\n              Expanded(\n                child: TextField(\n                  controller: _stepperController,\n                  submitFormatters: [\n                    TextInputFormatters.digitsOnly(\n                      min: _min,\n                      max: _max,\n                    ),\n                  ],\n                  onChanged: (text) {\n                    final parsed = double.tryParse(text);\n                    if (parsed != null) {\n                      _syncValue(parsed);\n                    }\n                  },\n                ),\n              ),\n              const Gap(8),\n              IconButton.outline(\n                density: ButtonDensity.iconDense,\n                size: ButtonSize.small,\n                icon: const Icon(Icons.add),\n                onPressed: () => _syncValue(value + 1),\n              ),\n            ],\n          ),\n        ),\n        const Gap(8),\n        Text('Value: ${value.toStringAsFixed(0)}').muted(),\n      ],\n    );\n  }\n}\n")
