B.aVO=new A.ai("Unified layout",A.cxq(),"import 'package:docs/shadcn_ui.dart';\n\n/// Unified diff layout \u2014 additions and deletions in a single column.\nclass FileDiffViewerExample1 extends StatelessWidget {\n  const FileDiffViewerExample1({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const FileDiffViewer(\n      files: [\n        FileDiff(\n          path: 'lib/src/auth/login.dart',\n          status: 'modified',\n          hunks: [\n            FileDiffHunk(\n              header: '@@ -1,6 +1,10 @@',\n              lines: [\n                FileDiffLine.deletion(\n                  oldLineNumber: 2,\n                  content: 'class LoginScreen extends StatelessWidget {',\n                ),\n                FileDiffLine.addition(\n                  newLineNumber: 2,\n                  content: 'class LoginScreen extends StatefulWidget {',\n                ),\n              ],\n            ),\n          ],\n        ),\n      ],\n      maxHeight: 320,\n    );\n  }\n}\n")
B.aXm=new A.ai("Split (side-by-side) layout",A.cxr(),"import 'package:docs/shadcn_ui.dart';\n\n/// Split layout \u2014 old version on the left, new on the right.\nclass FileDiffViewerExample2 extends StatelessWidget {\n  const FileDiffViewerExample2({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const FileDiffViewer(\n      layout: FileDiffLayout.split,\n      files: [ /* ... same FileDiff as example 1 ... */ ],\n      maxHeight: 320,\n    );\n  }\n}\n")
B.aWN=new A.ai("Multiple files with status badges",A.cxs(),"import 'package:docs/shadcn_ui.dart';\n\n/// Multi-file diff \u2014 added, renamed, and deleted files in one viewer.\nclass FileDiffViewerExample3 extends StatelessWidget {\n  const FileDiffViewerExample3({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const FileDiffViewer(\n      files: [\n        FileDiff(path: 'lib/src/utils/logger.dart', status: 'added', hunks: []),\n        FileDiff(\n          path: 'lib/src/utils/helpers.dart',\n          oldPath: 'lib/src/helpers.dart',\n          status: 'renamed',\n          hunks: [],\n        ),\n        FileDiff(path: 'lib/src/legacy/old_api.dart', status: 'deleted', hunks: []),\n      ],\n      maxHeight: 420,\n    );\n  }\n}\n")
