B.aXs=new A.ai("Vertical Example",A.cAV(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample1 extends StatefulWidget {\n  const StepperExample1({super.key});\n\n  @override\n  State<StepperExample1> createState() => _StepperExample1State();\n}\n\nclass _StepperExample1State extends State<StepperExample1> {\n  final StepperController controller = StepperController();\n\n  @override\n  Widget build(BuildContext context) {\n    return Stepper(\n      controller: controller,\n      // Vertical layout with 3 steps and Next/Prev actions.\n      direction: Axis.vertical,\n      steps: [\n        Step(\n          title: const Text('Step 1'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                const SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      // Advance to the next step.\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 1,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 2'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    // Move back one step.\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 2,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 3'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Finish'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 3,\n                height: 200,\n              ),\n            );\n          },\n        ),\n      ],\n    );\n  }\n}\n")
B.aVL=new A.ai("Horizontal Example",A.cAW(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample2 extends StatefulWidget {\n  const StepperExample2({super.key});\n\n  @override\n  State<StepperExample2> createState() => _StepperExample2State();\n}\n\nclass _StepperExample2State extends State<StepperExample2> {\n  final StepperController controller = StepperController();\n\n  @override\n  Widget build(BuildContext context) {\n    return Stepper(\n      controller: controller,\n      // Horizontal layout using the same 3-step flow.\n      direction: Axis.horizontal,\n      steps: [\n        Step(\n          title: const Text('Step 1'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                const SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 1,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 2'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 2,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 3'),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Finish'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 3,\n                height: 200,\n              ),\n            );\n          },\n        ),\n      ],\n    );\n  }\n}\n")
B.aVD=new A.ai("Failed Step Example",A.cAX(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample3 extends StatefulWidget {\n  const StepperExample3({super.key});\n\n  @override\n  State<StepperExample3> createState() => _StepperExample3State();\n}\n\nclass _StepperExample3State extends State<StepperExample3> {\n  final StepperController controller = StepperController(\n    stepStates: {\n      1: StepState.failed,\n    },\n    currentStep: 1,\n  );\n\n  @override\n  Widget build(BuildContext context) {\n    return Stepper(\n      controller: controller,\n      direction: Axis.horizontal,\n      steps: [\n        Step(\n          title: const Text('Step 1'),\n          contentBuilder: (context) {\n            return const StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                  child: Text('Next'),\n                ),\n              ],\n              child: NumberedContainer(\n                index: 1,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 2'),\n          contentBuilder: (context) {\n            return const StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                  child: Text('Next'),\n                ),\n              ],\n              child: NumberedContainer(\n                index: 2,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 3'),\n          contentBuilder: (context) {\n            return const StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                  child: Text('Finish'),\n                ),\n              ],\n              child: NumberedContainer(\n                index: 3,\n                height: 200,\n              ),\n            );\n          },\n        ),\n      ],\n    );\n  }\n}\n")
B.aY9=new A.ai("Clickable Step Example",A.cAY(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample4 extends StatefulWidget {\n  const StepperExample4({super.key});\n\n  @override\n  State<StepperExample4> createState() => _StepperExample4State();\n}\n\nclass _StepperExample4State extends State<StepperExample4> {\n  final StepperController controller = StepperController();\n\n  @override\n  Widget build(BuildContext context) {\n    return Stepper(\n      controller: controller,\n      direction: Axis.vertical,\n      steps: [\n        Step(\n          title: const Text('Step 1'),\n          icon: StepNumber(\n            onPressed: () {\n              // Tap on the step icon to jump directly to the step.\n              controller.jumpToStep(0);\n            },\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                const SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 1,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 2'),\n          icon: StepNumber(\n            onPressed: () {\n              controller.jumpToStep(1);\n            },\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 2,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 3'),\n          icon: StepNumber(\n            onPressed: () {\n              controller.jumpToStep(2);\n            },\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Finish'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 3,\n                height: 200,\n              ),\n            );\n          },\n        ),\n      ],\n    );\n  }\n}\n")
B.aX2=new A.ai("Custom Icon Example",A.cAZ(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample5 extends StatefulWidget {\n  const StepperExample5({super.key});\n\n  @override\n  State<StepperExample5> createState() => _StepperExample5State();\n}\n\nclass _StepperExample5State extends State<StepperExample5> {\n  final StepperController controller = StepperController();\n\n  @override\n  Widget build(BuildContext context) {\n    return Stepper(\n      controller: controller,\n      direction: Axis.horizontal,\n      steps: [\n        Step(\n          title: const Text('Step 1'),\n          icon: const StepNumber(\n            // You can customize the step icon, e.g., use a person icon.\n            icon: Icon(Icons.person),\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                const SecondaryButton(\n                  child: Text('Prev'),\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 1,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 2'),\n          icon: const StepNumber(\n            // Another custom icon for the second step.\n            icon: Icon(Icons.house_outlined),\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Next'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 2,\n                height: 200,\n              ),\n            );\n          },\n        ),\n        Step(\n          title: const Text('Step 3'),\n          icon: const StepNumber(\n            // And a briefcase icon for the third.\n            icon: Icon(Icons.work_outline),\n          ),\n          contentBuilder: (context) {\n            return StepContainer(\n              actions: [\n                SecondaryButton(\n                  child: const Text('Prev'),\n                  onPressed: () {\n                    controller.previousStep();\n                  },\n                ),\n                PrimaryButton(\n                    child: const Text('Finish'),\n                    onPressed: () {\n                      controller.nextStep();\n                    }),\n              ],\n              child: const NumberedContainer(\n                index: 3,\n                height: 200,\n              ),\n            );\n          },\n        ),\n      ],\n    );\n  }\n}\n")
B.aXy=new A.ai("Variants Example",A.cB_(),"import 'package:docs/pages/docs/components/carousel_example.dart';\nimport 'package:docs/shadcn_ui.dart';\n\nclass StepperExample6 extends StatefulWidget {\n  const StepperExample6({super.key});\n\n  @override\n  State<StepperExample6> createState() => _StepperExample6State();\n}\n\nclass _StepperExample6State extends State<StepperExample6> {\n  static const List<StepVariant> _variants = [\n    StepVariant.circle,\n    StepVariant.circleAlt,\n    StepVariant.line,\n  ];\n  static const List<String> _variantNames = [\n    'Circle',\n    'Circle Alt',\n    'Line',\n  ];\n  static const List<StepSize> _stepSize = StepSize.values;\n  static const List<String> _stepSizeNames = [\n    'Small',\n    'Medium',\n    'Large',\n  ];\n  final StepperController controller = StepperController();\n  int _currentVariant = 0;\n  int _currentStepSize = 0;\n  Axis direction = Axis.horizontal;\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          alignment: WrapAlignment.center,\n          crossAxisAlignment: WrapCrossAlignment.center,\n          runAlignment: WrapAlignment.center,\n          children: [\n            Toggle(\n              value: direction == Axis.horizontal,\n              onChanged: (value) {\n                if (value) {\n                  setState(() {\n                    direction = Axis.horizontal;\n                  });\n                } else {\n                  setState(() {\n                    direction = Axis.vertical;\n                  });\n                }\n              },\n              child: const Text('Horizontal'),\n            ),\n            Toggle(\n              value: direction == Axis.vertical,\n              onChanged: (value) {\n                if (value) {\n                  setState(() {\n                    direction = Axis.vertical;\n                  });\n                } else {\n                  setState(() {\n                    direction = Axis.horizontal;\n                  });\n                }\n              },\n              child: const Text('Vertical'),\n            ),\n            const VerticalDivider().sized(height: 16),\n            for (var i = 0; i < _variants.length; i++)\n              Toggle(\n                value: _currentVariant == i,\n                onChanged: (value) {\n                  setState(() {\n                    // Choose among visual variants (circle, alt circle, line).\n                    _currentVariant = i;\n                  });\n                },\n                child: Text(_variantNames[i]),\n              ),\n            const VerticalDivider().sized(height: 16),\n            for (var i = 0; i < _stepSize.length; i++)\n              Toggle(\n                value: _currentStepSize == i,\n                onChanged: (value) {\n                  setState(() {\n                    // Pick the step size used by the Stepper.\n                    _currentStepSize = i;\n                  });\n                },\n                child: Text(_stepSizeNames[i]),\n              ),\n            const VerticalDivider().sized(height: 16),\n            AnimatedBuilder(\n              animation: controller,\n              builder: (context, child) {\n                return Toggle(\n                  value: controller.value.stepStates[1] == StepState.failed,\n                  onChanged: (value) {\n                    if (value) {\n                      // Mark step 2 as failed to demo error state.\n                      controller.setStatus(1, StepState.failed);\n                    } else {\n                      controller.setStatus(1, null);\n                    }\n                  },\n                  child: const Text('Toggle Error'),\n                );\n              },\n            ),\n          ],\n        ),\n        const Gap(16),\n        Stepper(\n          controller: controller,\n          direction: direction,\n          // Apply the chosen size and visual variant.\n          size: _stepSize[_currentStepSize],\n          variant: _variants[_currentVariant],\n          steps: [\n            Step(\n              title: const Text('Step 1'),\n              contentBuilder: (context) {\n                return StepContainer(\n                  actions: [\n                    const SecondaryButton(\n                      child: Text('Prev'),\n                    ),\n                    PrimaryButton(\n                        child: const Text('Next'),\n                        onPressed: () {\n                          controller.nextStep();\n                        }),\n                  ],\n                  child: const NumberedContainer(\n                    index: 1,\n                    height: 200,\n                  ),\n                );\n              },\n            ),\n            Step(\n              title: const StepTitle(\n                title: Text('Step 2'),\n                subtitle: Text('Optional Step'),\n              ),\n              contentBuilder: (context) {\n                return StepContainer(\n                  actions: [\n                    SecondaryButton(\n                      child: const Text('Prev'),\n                      onPressed: () {\n                        controller.previousStep();\n                      },\n                    ),\n                    PrimaryButton(\n                        child: const Text('Next'),\n                        onPressed: () {\n                          controller.nextStep();\n                        }),\n                  ],\n                  child: const NumberedContainer(\n                    index: 2,\n                    height: 200,\n                  ),\n                );\n              },\n            ),\n            Step(\n              title: const Text('Step 3'),\n              contentBuilder: (context) {\n                return StepContainer(\n                  actions: [\n                    SecondaryButton(\n                      child: const Text('Prev'),\n                      onPressed: () {\n                        controller.previousStep();\n                      },\n                    ),\n                    PrimaryButton(\n                        child: const Text('Finish'),\n                        onPressed: () {\n                          controller.nextStep();\n                        }),\n                  ],\n                  child: const NumberedContainer(\n                    index: 3,\n                    height: 200,\n                  ),\n                );\n              },\n            ),\n          ],\n        ),\n      ],\n    );\n  }\n}\n")
